#!/usr/bin/env bash
# gen-seo.sh — regenerate docs/sitemap.xml, docs/llms.txt and docs/llms-full.txt
# from docs/_sidebar.md and the pages it links.
#
# Every page the sidebar links must carry exactly one summary comment on
# line 1 (hand-written pages) or line 2 (generated pages, after the
# "Generated by" notice):
#
#   <!-- summary: One complete standalone sentence, 1 to 200 characters. -->
#
# The summary is used verbatim as the page description in llms.txt; it is
# never truncated. A missing, empty, duplicate or oversized summary fails the
# run and lists the offending files.
#
# llms-full.txt inlines the home page and the operator guides once each, in
# sidebar order, as H2 sections with their headings shifted down one level.
# It omits generated command pages, design docs, the contributor lab,
# navigation files and relocation stubs (fewer than 5 non-empty lines and
# the word "moved").
#
# Run before committing docs changes. CI validates freshness via --check.
# docs/commands.json is written by `splunkctl docs generate`, not here.
#
# docs/assets/og.png (social link preview) is a static asset, regenerated
# manually only when docs/assets/og.svg changes.
set -euo pipefail

check=false
[ "${1:-}" = "--check" ] && check=true

root="$(cd "$(dirname "$0")/.." && pwd)"
docs="$root/docs"
sidebar="$docs/_sidebar.md"
base="https://splunkctl.danny.vn"
summary_max=200
# Sidebar pages that never go into llms-full.txt (glob patterns on the href).
llms_full_skip=("commands/*" "design/*" "guides/keycloak-lab.md")

[ -f "$sidebar" ] || { echo "error: $sidebar not found" >&2; exit 1; }

outdir="$(mktemp -d)"
trap 'rm -rf "$outdir"' EXIT

# --- sidebar parsing -------------------------------------------------------
# One record per line: "section<TAB><name>" or "page<TAB><title><TAB><href>".
# External (http) links are dropped; they are not pages of this site.
entries="$(awk '
  /^- \*\*.*\*\*$/ {
    s = $0; sub(/^- \*\*/, "", s); sub(/\*\*$/, "", s)
    print "section\t" s; next
  }
  /^[ ]*- \[/ {
    line = $0
    if (!match(line, /\[[^]]*\]/)) next
    title = substr(line, RSTART + 1, RLENGTH - 2)
    rest = substr(line, RSTART + RLENGTH)
    if (!match(rest, /\([^)]*\)/)) next
    href = substr(rest, RSTART + 1, RLENGTH - 2)
    if (href ~ /^https?:/) next
    print "page\t" title "\t" href
  }
' "$sidebar")"

# page_file HREF -> path of the markdown file behind a sidebar href
page_file() {
  local href="$1"
  [ "$href" = "/" ] && { echo "$docs/README.md"; return; }
  local f="$docs/$href"
  [[ "$href" == */ ]] && f="${f}README.md"
  [ -d "$f" ] && f="$f/README.md"
  echo "$f"
}

# page_rel HREF -> path relative to docs/ (README.md for home)
page_rel() {
  local f; f="$(page_file "$1")"
  echo "${f#"$docs"/}"
}

# page_route HREF -> hash-router path ("" for home)
page_route() {
  local p="${1%.md}"; p="${p%/}"
  echo "$p"
}

# --- summaries --------------------------------------------------------------
# read_summary FILE -> prints "<status>\t<summary>"; status is ok, missing,
# empty, duplicate or oversized.
read_summary() {
  local file="$1" count summary status="ok"
  count="$(grep -c '^<!-- summary:' "$file" || true)"
  summary="$(awk '
    NR <= 2 && /^<!-- summary:.*-->$/ {
      s = $0; sub(/^<!-- summary:/, "", s); sub(/-->$/, "", s)
      gsub(/^[ \t]+|[ \t]+$/, "", s)
      print s; exit
    }
    NR > 2 { exit }
  ' "$file")"
  if [ "$count" -gt 1 ]; then
    status="duplicate"
  elif [ "$count" -eq 0 ] || ! head -n 2 "$file" | grep -q '^<!-- summary:'; then
    status="missing"
  elif [ -z "$summary" ]; then
    status="empty"
  elif [ "${#summary}" -gt "$summary_max" ]; then
    status="oversized"
  fi
  printf '%s\t%s\n' "$status" "$summary"
}

# summary_for REL -> the validated summary of docs/REL
summaries="$outdir/summaries.tsv"
: > "$summaries"
summary_for() {
  awk -F '\t' -v k="$1" '$1 == k { print $2; exit }' "$summaries"
}

errors=()
while IFS=$'\t' read -r kind title href; do
  [ "$kind" = "page" ] || continue
  file="$(page_file "$href")"
  rel="$(page_rel "$href")"
  if [ ! -f "$file" ]; then
    errors+=("missing file: docs/$rel (linked from _sidebar.md as $href)")
    continue
  fi
  IFS=$'\t' read -r status summary < <(read_summary "$file")
  case "$status" in
    ok) printf '%s\t%s\n' "$rel" "$summary" >> "$summaries" ;;
    *) errors+=("$status summary: docs/$rel") ;;
  esac
done <<< "$entries"

if [ "${#errors[@]}" -gt 0 ]; then
  echo "error: every page linked from docs/_sidebar.md needs exactly one" >&2
  echo "  '<!-- summary: One sentence (1-$summary_max chars). -->' on line 1 or 2:" >&2
  for e in "${errors[@]}"; do echo "  $e" >&2; done
  exit 1
fi

home_summary="$(summary_for README.md)"

# --- sitemap.xml ------------------------------------------------------------

{
  echo '<?xml version="1.0" encoding="UTF-8"?>'
  echo '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'
  while IFS=$'\t' read -r kind title href; do
    [ "$kind" = "page" ] || continue
    route="$(page_route "$href")"
    if [ -z "$route" ]; then
      echo "  <url><loc>${base}/#/</loc><priority>1.0</priority></url>"
      continue
    fi
    case "$route" in guides/*) pri="0.8" ;; *) pri="0.6" ;; esac
    echo "  <url><loc>${base}/#/${route}</loc><priority>${pri}</priority></url>"
  done <<< "$entries"
  echo '</urlset>'
} > "$outdir/sitemap.xml"

# --- llms.txt ---------------------------------------------------------------

{
  echo "# splunkctl"
  echo ""
  echo "> ${home_summary}"
  echo ""
  echo "- [Home](${base}/README.md): ${home_summary}"
  echo ""
  echo "## Machine-readable"
  echo ""
  echo "- [llms-full.txt](${base}/llms-full.txt): The home page and every operator guide in one markdown file."
  echo "- [commands.json](${base}/commands.json): The full command tree with parameters, defaults and guard markers, as printed by \`splunkctl commands --json\`."
  while IFS=$'\t' read -r kind title href; do
    if [ "$kind" = "section" ]; then
      echo ""
      echo "## ${title}"
      echo ""
      continue
    fi
    [ "$kind" = "page" ] && [ "$href" != "/" ] || continue
    rel="$(page_rel "$href")"
    echo "- [${title}](${base}/${rel}): $(summary_for "$rel")"
  done <<< "$entries"
  echo ""
  echo "## Links"
  echo ""
  echo "- [GitHub](https://github.com/dannyota/splunkctl): Source code and releases"
  echo "- [PyPI](https://pypi.org/project/splunkctl/): Python package"
} > "$outdir/llms.txt"

# --- llms-full.txt ----------------------------------------------------------

# is_stub FILE -> true for a relocation stub
is_stub() {
  awk '
    /^<!-- .* -->$/ && NR <= 2 { next }
    NF { n++; if (tolower($0) ~ /moved/) moved = 1 }
    END { exit !(n < 5 && moved) }
  ' "$1"
}

# render_section FILE REL TITLE: H2 + source line + body with headings shifted
# one level and relative links made absolute. Fenced code is left untouched.
render_section() {
  local file="$1" rel="$2" title="$3" dir
  dir="$(dirname "$rel")"; [ "$dir" = "." ] && dir=""
  find "$docs" -name '*.md' | sed "s#^$docs/##" | awk \
    -v base="$base" -v dir="$dir" -v title="$title" -v url="$base/$rel" '
    function absolute(t,    anchor, p) {
      if (t ~ /^(https?:|mailto:)/) return t
      if (t ~ /^#\//) return base "/" t
      if (t ~ /^#/) return t
      if (t ~ /^\//) return base t
      p = t; anchor = ""
      if (match(p, /#.*$/)) { anchor = substr(p, RSTART); p = substr(p, 1, RSTART - 1) }
      if (dir != "" && p ~ /^\.\.\//) { p = substr(p, 4) }
      else if (dir != "" && !(p in files) && ((dir "/" p) in files)) { p = dir "/" p }
      return base "/" p anchor
    }
    function links(line,    out, t, s, l) {
      out = ""
      while (match(line, /\]\([^)]+\)/)) {
        s = RSTART; l = RLENGTH  # absolute() runs match() too
        t = substr(line, s + 2, l - 3)
        out = out substr(line, 1, s) "(" absolute(t) ")"
        line = substr(line, s + l)
      }
      return out line
    }
    function header(h) { print "## " h; print ""; print "Source: " url; print ""; started = 1 }
    FNR == NR { files[$0] = 1; next }
    FNR <= 2 && /^<!-- .* -->$/ { next }
    /^(```|~~~)/ { fence = !fence; print; next }
    fence { print; next }
    !started && /^# / { h = $0; sub(/^# +/, "", h); header(h); next }
    !started && NF { header(title) }
    !started { next }
    /^#+ / { print "#" links($0); next }
    { print links($0) }
  ' - "$file"
}

{
  echo "# splunkctl documentation"
  echo ""
  echo "> ${home_summary}"
  echo ""
  echo "Each section below is one page of ${base}, linked by its source URL."
  echo "The generated command reference is kept separate: browse ${base}/#/commands/README"
  echo "(raw: ${base}/commands/README.md) or load ${base}/commands.json for the"
  echo "machine-readable command tree. Index: ${base}/llms.txt"
  seen=$'\n'
  while IFS=$'\t' read -r kind title href; do
    [ "$kind" = "page" ] || continue
    skip=false
    for pat in "${llms_full_skip[@]}"; do
      # shellcheck disable=SC2254
      case "$href" in $pat) skip=true ;; esac
    done
    $skip && continue
    file="$(page_file "$href")"
    rel="$(page_rel "$href")"
    case "$seen" in *$'\n'"$rel"$'\n'*) continue ;; esac
    seen="${seen}${rel}"$'\n'
    is_stub "$file" && continue
    echo ""
    render_section "$file" "$rel" "$title"
  done <<< "$entries"
} > "$outdir/llms-full.txt"

# --- check or write ---------------------------------------------------------

if $check; then
  stale=false
  for f in sitemap.xml llms.txt llms-full.txt; do
    if ! diff -q "$outdir/$f" "$docs/$f" >/dev/null 2>&1; then
      echo "stale: $f" >&2
      stale=true
    fi
  done
  if $stale; then
    echo "Run: bash scripts/gen-seo.sh" >&2
    exit 1
  fi
  echo "ok: SEO files up-to-date"
else
  for f in sitemap.xml llms.txt llms-full.txt; do cp "$outdir/$f" "$docs/$f"; done
  echo "generated: sitemap.xml ($(grep -c '<url>' "$docs/sitemap.xml") URLs), llms.txt ($(wc -l < "$docs/llms.txt" | tr -d ' ') lines), llms-full.txt ($(wc -c < "$docs/llms-full.txt" | tr -d ' ') bytes)"
fi
